import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@RunWith(MockitoJUnitRunner.class)
public class BankAccountTest {
    @Mock
    private BankAccount bankAccount;

    @InjectMocks
    private BankService bankService;

    @Test
    public void testWithdrawFundsInParallel() throws InterruptedException {
        // Set up the test data
        double initialBalance = 100.0;
        double withdrawalAmount = 50.0;

        // Set up the bank account
        bankAccount.setBalance(initialBalance);

        // Create a CountDownLatch to synchronize the threads
        CountDownLatch latch = new CountDownLatch(2);

        // Create two threads that will withdraw funds from the bank account in parallel
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> {
            bankService.withdrawFunds(bankAccount, withdrawalAmount);
            latch.countDown();
        });
        executor.submit(() -> {
            bankService.withdrawFunds(bankAccount, withdrawalAmount);
            latch.countDown();
        });

        // Wait for the threads to complete
        latch.await();

        // Assert that the balance is correct
        assertEquals(initialBalance - 2 * withdrawalAmount, bankAccount.getBalance(), 0.01);
    }
}
```

